import { expect, it } from "vitest";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { createCommandArguments } from "safe-bash-contracts/command";
import { createMagickCommand, runConvertCli, runConvertCliSync } from "./index.js";

// Uncompressed TIFFs and exact info output generated by ImageMagick 7.1.2-31.
const fixtures = [
  {
    "name": "RightTop",
    "base64": "",
    "expected": "72|72|PixelsPerInch"
  },
  {
    "name": "PixelsPerInch",
    "base64": "",
    "expected": "120|120|PixelsPerInch"
  },
  {
    "name": "PixelsPerCentimeter",
    "base64": "",
    "expected": "120|120|PixelsPerCentimeter"
  }
];

it("keeps the oriented TIFF fixture free of resolution tags", () => {
  const bytes = Buffer.from(fixtures[0]!.base64, "base64");
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const little = view.getUint16(0) === 0x4949;
  const ifd = view.getUint32(4, little);
  const tags = Array.from({ length: view.getUint16(ifd, little) }, (_, i) => view.getUint16(ifd + 2 + i * 12, little));
  expect(tags).toContain(274);
  for (const tag of [282, 283, 296]) expect(tags).not.toContain(tag);
});

for (const mode of ["sync", "buffered", "retained", "command"] as const) {
  it.each([...fixtures, { name: "canvas", base64: "", expected: "72|72|Undefined" }])(
    `reports native resolution units (${mode}, $name)`, async ({ name, base64, expected }) => {
      const files = new Map([["/input.tif", Buffer.from(base64, "base64")], ["/out", Buffer.from("KEEP")]]);
      const fs = new MemoryFileSystem();
      for (const [path, bytes] of files) await fs.writeFile(path, bytes);
      const args = [name === "canvas" ? "xc:red" : "/input.tif", "-format", "%x|%y|%U", "info:/out"];
      let stdout = "", stderr = "";
      const argumentValues = createCommandArguments(args);
      const result = mode === "command" ? await createMagickCommand().execute({
        command: "magick", args: argumentValues.args, argumentValues, fs, cwd: "/", env: {},
        stdin: (async function* () {})(), signal: new AbortController().signal,
        stdout: { async write(chunk) { stdout += new TextDecoder().decode(chunk); } },
        stderr: { async write(chunk) { stderr += new TextDecoder().decode(chunk); } }
      }) : mode === "sync" ? runConvertCliSync(args, files)
        : await runConvertCli(args, mode === "retained" ? { filesystem: fs, cwd: "/" } : files);
      expect({ stdout, stderr, ...result }).toEqual({ exitCode: 0, stdout: "", stderr: "" });
      const output = mode === "command" || mode === "retained" ? await fs.readFile("/out") : files.get("/out")!;
      expect(new TextDecoder().decode(output)).toBe(expected);
    });
}
